
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_htbs_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_htbs", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.295496971689150e+00, -4.213367586324521e+00, -4.098346811144066e+00, -3.939141391100170e+00, -3.722458685607056e+00, -3.434567785937354e+00, -3.064935079987779e+00, -2.612603846683634e+00, -2.095294891463509e+00, -1.564441717237956e+00, -1.084145713370655e+00, -7.044077575235095e-01, -6.016246562153624e-01, -4.982221765774597e-01, -3.638258988558689e-01, -2.424856978649347e-01, -1.464229079360340e-01, -5.042689670088744e-02, -1.082147707426292e-02, -1.216216050001396e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


